remediation.scriptTemplate:
# Diagnose: Check serialized data signing SettingOverride status
Get-SettingOverride | Where-Object { $_.ComponentName -eq 'Data' -and $_.SectionName -eq 'EnableSerializationDataSigning' } | Select-Object Name, ComponentName, SectionName, Parameters, Server | Format-List
# Expected: an override with Parameters containing 'Enabled=True' applied globally or to target servers.

# Compare the active Exchange Server Auth Certificate across all servers.
$authThumbprint = (Get-AuthConfig).CurrentCertificateThumbprint
Get-ExchangeServer | ForEach-Object {
    $server = $_.Name
    $certificate = Get-ExchangeCertificate -Server $server | Where-Object { $_.Thumbprint -eq $authThumbprint }
    [pscustomobject]@{
        Server = $server
        ActiveAuthCertificateFound = [bool]$certificate
        Thumbprint = $authThumbprint
    }
}
